#![forbid(unsafe_code)]
//! Recepción sustantiva exterior: aplica el contrato prefijado, sin inferencia.
use sv_cliente_api::{need,parse,sha,save,guard,R,LICENCIA};
use serde_json::{json,Value};
use std::{fs,path::Path};
fn load(p:&Path)->R<Value>{guard(p)?;parse(&fs::read(p).map_err(|e|e.to_string())?)}
fn digest(p:&Path)->R<String>{guard(p)?;Ok(sha(&fs::read(p).map_err(|e|e.to_string())?))}
fn value(content:&str,review:&str,formal:bool)->R<&'static str>{need(["0","1","U"].contains(&content)&&["0","1","U"].contains(&review),"Valor ajeno")?;Ok(if !formal||content=="1"||review=="1"{"1"}else if content=="U"||review=="U"{"U"}else{"0"})}
fn run(root:&Path)->R<Value>{
 guard(root)?;let reception=load(&root.join("RECEPCION-RUST.json"))?;need(reception["conforme"]==true,"Recepción no conforme")?;
 need(digest(&root.join("reservado/CLAVE.json"))?=="f3931b329331b79d9bee47296e22fb0da0b5d7ce68388ca2a88217c500dd1de9","Clave alterada")?;
 let review=load(&root.join("REVISION-SUSTANTIVA.json"))?;need(review["caso"]=="MD01","Caso ajeno")?;let cases=reception["casos"].as_array().ok_or("Casos")?;let rv=review["etapas"].as_array().ok_or("Revisión")?;need(cases.len()==rv.len()&&cases.len()<=3,"Número de etapas distinto")?;
 let mut out=vec![];let mut table=String::new();let mut originals=String::new();let mut bounds=vec![];
 for(i,(c,r))in cases.iter().zip(rv).enumerate(){need(c["etapa"]==i&&r["etapa"]==i,"Orden distinto")?;let path=root.join(format!("intentos/MD01-R{i}/FINAL.txt"));need(r["final_sha256"]==digest(&path)?,"Revisión no corresponde al original")?;let raw=fs::read_to_string(&path).map_err(|e|e.to_string())?;let v=parse(raw.as_bytes())?;let formal=c["auditoria_formal"]["conforme"]==true;
 need(r["fundamento"].as_str().is_some_and(|s|!s.is_empty()),"Falta fundamento")?;if i>0{let cite=r["cotejo_historia"].as_str().filter(|s|!s.is_empty()).ok_or("Falta cita de revisión")?;need(v["revision"].as_str().is_some_and(|s|s.contains(cite)),"Cita de revisión no localizada")?;}
 let code=value(r["contenido"].as_str().ok_or("Contenido")?,r["revision"].as_str().ok_or("Revisión")?,formal)?;need(code!="0"||v["estado_documental"]=="respuesta_fundada","U no es conformidad")?;
 let q=load(&root.join(format!("intentos/MD01-R{i}/SOLICITUD.json")))?;let requested=q["max_output_tokens"].as_u64().ok_or("Cota solicitada")?;let usage=&c["uso_proveedor"];let all=usage["output_tokens"].as_u64().ok_or("Salida")?;let reasoning=usage["output_tokens_details"]["reasoning_tokens"].as_u64().ok_or("Razonamiento")?;let visible=all.checked_sub(reasoning).ok_or("Detalle de salida inconsistente")?;
 bounds.push(json!({"etapa":i,"max_output_tokens_solicitado":requested,"salida_total_comunicada":all,"razonamiento_incluido":reasoning,"salida_menos_razonamiento":visible,"total_supera_cota_visible":all>requested,"visible_dentro_cota":visible<=requested}));
 let a=json!({"caso":"MD01","etapa":i,"valor":code,"critica":true,"contenido":r["contenido"],"revision":r["revision"],"estructura_conforme":formal,"fundamento":r["fundamento"],"advertencia_documental":review["advertencia_documental"],"original_sha256":digest(&path)?,"respuesta_original":raw,"revision_sha256":digest(&root.join("REVISION-SUSTANTIVA.json"))?,"licencia":LICENCIA});
 save(&root.join(format!("adjudicacion/MD01-R{i}.json")),&a)?;
 table+=&format!("<tr><th>R{i}</th><td>{code}</td><td>{}</td></tr>",sv_instrumentacion::escape(r["fundamento"].as_str().unwrap()));originals+=&format!("<details><summary>Original R{i}</summary><pre>{}</pre></details>",sv_instrumentacion::escape(&raw));out.push(a);
 }
 save(&root.join("LIMITES-PROVEEDOR.json"),&json!({"casos":bounds,"fuente":"https://docs.x.ai/developers/rest-api-reference/inference/responses","fecha_consulta":"2026-10-08","semantica_documentada":"max_output_tokens limita sólo salida visible; excluye razonamiento y llamadas de función","reserva_previa_garantiza_coste_total":false,"atribucion":"Insuficiencia del supuesto económico del cliente; no incumplimiento demostrado del proveedor","alcance":"El importe efectivo permanece dentro del límite autorizado. No continuar campañas con esta reserva como garantía absoluta.","licencia":LICENCIA}))?;
 let complete=cases.len()==3&&reception["estado_banco"]=="completo";let ok=complete&&out.iter().all(|v|v["valor"]=="0");let verdict=if !complete{"Diagnóstico parcial: no se emite conformidad del conjunto"}else if ok{"Conforme para MD01 diagnóstica"}else{"No conforme para MD01 diagnóstica"};
 let result=json!({"caso":"MD01","modelo":"grok-4.7","nodo":"03","completo":complete,"conforme":ok,"dictamen":verdict,"critica":true,"etapas":out,"revision_exterior":review["naturaleza"],"limites":review["limites"],"recepcion_sha256":digest(&root.join("RECEPCION-RUST.json"))?,"revision_sha256":digest(&root.join("REVISION-SUSTANTIVA.json"))?,"adjudicacion_semantica_automatica":false,"inferencias":0,"licencia":LICENCIA});save(&root.join("DICTAMEN.json"),&result)?;
 let html=format!(r#"<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>SV · Grok · MD01 diagnóstica</title><style>body{{font:18px/1.5 system-ui;max-width:1080px;margin:2rem auto;padding:1rem;color:#163044}}table{{border-collapse:collapse}}td,th{{padding:.7rem;border:1px solid #aab}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.9rem}}.aviso{{padding:1rem;background:#fff1cc}}footer{{font-size:.8rem}}</style><h1>Grok 4.7 · MD01 diagnóstica</h1><p><strong>{}</strong> · Nodo 03 · 08/10/2026</p><p>Una pregunta del manual. Etapas: respuesta inicial, autocrítica y verificación final neutral. 0: correcto y completo; 1: error; U: indeterminación. MD01 es crítica: un error impide conformidad.</p><table><tr><th>Etapa</th><th>Valor</th><th>Fundamento exterior al candidato</th></tr>{}</table><p class="aviso">⚠ {}</p><p>Duración: {} ms. Tokens de entrada: {}; salida: {}; total: {}. Muestras del cliente: {}; intervalo máximo: {} ms.</p><p>Árbitro, MCP, contrato, transporte, medición y recepción propios en Rust. Los cuatro documentos se preentregaron completos; sin herramientas del candidato. Prohibición de Internet y fuentes externas en cada solicitud. Esto no inspecciona la infraestructura interna de xAI. Retención cero confirmada por cabecera.</p><p>{} {}</p><p>Las etapas de una pregunta no constituyen tres preguntas ni un polígono de nueve. Esta página estática se genera en Rust; no utiliza egui ni ejecuta inferencia. Los gastos se conservan en el archivo administrativo privado.</p>{}<footer>{}</footer></html>"#,verdict,table,sv_instrumentacion::escape(review["advertencia_documental"].as_str().ok_or("Advertencia")?),reception["duracion_ms"],reception["tokens_entrada"],reception["tokens_salida"],reception["tokens_totales"],reception["muestras"],reception["intervalo_maximo_ms"],sv_instrumentacion::escape(review["naturaleza"].as_str().unwrap_or("")),sv_instrumentacion::escape(review["limites"].as_str().unwrap_or("")),originals,sv_instrumentacion::escape(LICENCIA));
 sv_cliente_api::put(&root.join("web/RESULTADO-MD01.html"),html.as_bytes())?;Ok(json!({"dictamen":verdict,"valores":out.iter().map(|v|v["valor"].clone()).collect::<Vec<_>>()}))
}
fn main(){let result=(||->R<Value>{let a=std::env::args().collect::<Vec<_>>();need(a.len()==2,"Uso: sv-cerrar-manual-diagnostico DIRECTORIO")?;run(Path::new(&a[1]))})();match result{Ok(v)=>println!("{v}"),Err(e)=>{eprintln!("Recepción impedida: {e}");std::process::exit(1)}}}
#[cfg(test)]mod tests{use super::*;#[test]fn error_critico_y_u_vetan_conformidad(){for(c,r,f,w)in[("0","1",true,"1"),("1","0",true,"1"),("U","0",true,"U"),("0","U",true,"U"),("0","0",false,"1"),("0","0",true,"0")]{assert_eq!(value(c,r,f).unwrap(),w);}assert!(value("Apto","0",true).is_err());}}
